use crate::{field::{E,F,P,Z,scalar,poly},jac::{C,D}};
#[derive(Clone)]pub struct Term{pub a:P,pub y:bool,pub den:P,pub power:u64}
pub struct Fun{pub terms:Vec<Term>,pub lead:E}
fn tracked(c:&C,a:&D,b:&D)->(D,Vec<Term>){let f=c.f;if a.u.len()==1{return(b.clone(),vec![])}if b.u.len()==1{return(a.clone(),vec![])}let(d1,e1,e2)=c.xgcd(&a.u,&b.u);let(d,c1,c2)=c.xgcd(&d1,&f.pa(&a.v,&b.v));let s1=f.pm(&c1,&e1);let s2=f.pm(&c1,&e2);let mut u=c.exact(&f.pm(&a.u,&b.u),&f.pm(&d,&d));let t1=f.pm(&f.pm(&s1,&a.u),&b.v);let t2=f.pm(&f.pm(&s2,&b.u),&a.v);let t3=f.pm(&c2,&f.pa(&f.pm(&a.v,&b.v),&c.ff));let mut v=c.exact(&f.pa(&f.pa(&t1,&t2),&t3),&d);u=f.monic(&u);v=f.rem(&v,&u);let mut terms=vec![Term{a:d,y:false,den:poly(&[1]),power:1}];while u.len()>c.g+1{let next=f.monic(&c.exact(&f.ps(&c.ff,&f.pm(&v,&v)),&u));terms.push(Term{a:f.ps(&vec![],&v),y:true,den:next.clone(),power:1});v=f.rem(&f.ps(&vec![],&v),&next);u=next}let out=D{u,v};assert_eq!(out,c.add(a,b));(out,terms)}
fn lead(f:&F,t:&Term)->E{let na=if t.y&&2*t.a.len().saturating_sub(1)<9{scalar(1)}else{*t.a.last().unwrap()};f.mul(na,f.inv(*t.den.last().unwrap()))}
pub fn four(c:&C,p:&D)->Fun{let(d,mut a)=tracked(c,p,p);let(z,b)=tracked(c,&d,&d);assert_eq!(z,c.zero());for t in &mut a{t.power*=2}a.extend(b);let mut lc=scalar(1);for t in &a{lc=c.f.mul(lc,c.f.pow(lead(c.f,t),t.power))}Fun{terms:a,lead:lc}}
pub fn closed(c:&C,h:&D,a:E)->Fun{let f=c.f;let s=f.sub(Z,f.mul(f.eval(&h.v,a),f.inv(f.eval(&h.u,a))));let vg=f.pa(&h.v,&c.scale(&h.u,s));assert_eq!(f.ps(&c.ff,&f.pm(&vg,&vg)),f.pm(&vec![f.sub(Z,a),scalar(1)],&f.pm(&h.u,&h.u)));Fun{terms:vec![Term{a:f.ps(&vec![],&vg),y:true,den:vec![f.sub(Z,a),scalar(1)],power:2},Term{a:vec![f.sub(Z,a),scalar(1)],y:false,den:poly(&[1]),power:1}],lead:scalar(1)}}
pub fn norm(f:&F,u:&P,h:&P)->E{let n=u.len()-1;if n==0{return scalar(1)}let mut matrix=vec![vec![Z;n];n];let mut col=f.rem(h,u);for j in 0..n{for(i,&a)in col.iter().enumerate(){matrix[i][j]=a}col=f.rem(&f.pm(&col,&poly(&[0,1])),u)}let mut det=scalar(1);for j in 0..n{let Some(i)=(j..n).find(|&i|matrix[i][j]!=Z)else{return Z};if i!=j{matrix.swap(i,j);det=f.sub(Z,det)}let pivot=matrix[j][j];det=f.mul(det,pivot);let inv=f.inv(pivot);for i in j+1..n{let z=f.mul(matrix[i][j],inv);for k in j+1..n{matrix[i][k]=f.sub(matrix[i][k],f.mul(z,matrix[j][k]))}matrix[i][j]=Z}}det}
pub fn finite(c:&C,h:&Fun,d:&D)->Option<E>{let f=c.f;let mut value=scalar(1);for t in &h.terms{let a=if t.y{f.pa(&t.a,&d.v)}else{t.a.clone()};let n=norm(f,&d.u,&a);let dd=norm(f,&d.u,&t.den);if n==Z||dd==Z{return None}value=f.mul(value,f.pow(f.mul(n,f.inv(dd)),t.power))}Some(f.mul(value,f.inv(f.pow(h.lead,(d.u.len()-1)as u64))))}
pub fn point(c:&C,h:&Fun,x:E,y:E)->Option<E>{let f=c.f;let mut value=scalar(1);for t in &h.terms{let a=f.add(f.eval(&t.a,x),if t.y{y}else{Z});let b=f.eval(&t.den,x);if a==Z||b==Z{return None}value=f.mul(value,f.pow(f.mul(a,f.inv(b)),t.power))}Some(f.mul(value,f.inv(h.lead)))}
pub fn pair(c:&C,a:&D,b:&D,fa:&Fun,fb:&Fun,roots:&[E])->Option<(E,usize)>{assert_eq!(a.u.len(),5);assert_eq!(b.u.len(),5);let f=c.f;let aa=finite(c,fa,b)?;let bb=finite(c,fb,a)?;let direct=f.mul(aa,f.inv(bb));for(i,&r)in roots.iter().enumerate(){let u=f.eval(&a.u,r);if u==Z||f.eval(&b.u,r)==Z{continue}let Some(fr)=point(c,fa,r,Z)else{continue};let numerator=f.mul(aa,f.inv(f.pow(fr,4)));let denominator=f.mul(bb,f.inv(f.pow(u,8)));let moved=f.mul(numerator,f.inv(denominator));assert_eq!(moved,direct,"moved-divisor normalization");assert_eq!(f.pow(direct,4),scalar(1));return Some((direct,i))}None}
